class Solution {
public:
    int minRefuelStops(int target, int startFuel, vector<vector<int>>& stations) {
        priority_queue<int> pq;
        int stops = 0;
        long long cur_fuel = startFuel;
        int prev_pos = 0;
        stations.push_back({target, 0});
        for (auto& s : stations) {
            int pos = s[0], fuel = s[1];
            cur_fuel -= (pos - prev_pos);
            while (!pq.empty() && cur_fuel < 0) {
                cur_fuel += pq.top();
                pq.pop();
                stops++;
            }
            if (cur_fuel < 0) return -1;
            pq.push(fuel);
            prev_pos = pos;
        }
        return stops;
    }
};

class Solution {
    public int minRefuelStops(int target, int startFuel, int[][] stations) {
        PriorityQueue<Integer> pq = new PriorityQueue<>((a, b) -> b - a);
        int stops = 0;
        long curFuel = startFuel;
        int prevPos = 0;
        int n = stations.length;
        for (int i = 0; i <= n; i++) {
            int pos = (i < n) ? stations[i][0] : target;
            int fuel = (i < n) ? stations[i][1] : 0;
            curFuel -= (pos - prevPos);
            while (!pq.isEmpty() && curFuel < 0) {
                curFuel += pq.poll();
                stops++;
            }
            if (curFuel < 0) return -1;
            pq.offer(fuel);
            prevPos = pos;
        }
        return stops;
    }
}

var minRefuelStops = function(target, startFuel, stations) {
    const pq = [];
    function push(val) {
        pq.push(val);
        pq.sort((a, b) => b - a);
    }
    let stops = 0;
    let curFuel = startFuel;
    let prevPos = 0;
    const allStations = [...stations, [target, 0]];
    for (const [pos, fuel] of allStations) {
        curFuel -= (pos - prevPos);
        while (pq.length > 0 && curFuel < 0) {
            curFuel += pq.shift();
            stops++;
        }
        if (curFuel < 0) return -1;
        push(fuel);
        prevPos = pos;
    }
    return stops;
};
